package com.oracle.banking.twofa.controller;
import com.oracle.banking.shared.constants.SecurityConstants; import com.oracle.banking.twofa.dto.TwoFactorDtos.*; import com.oracle.banking.twofa.exception.UnauthorizedException; import com.oracle.banking.twofa.service.TwoFactorService; import jakarta.validation.Valid; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/internal/twofa") public class InternalTwoFactorController {private final TwoFactorService s;private final String key;public InternalTwoFactorController(TwoFactorService s,@Value("${services.internal-api-key}") String k){this.s=s;key=k;}@GetMapping("/users/{userId}/status") StatusResponse status(@PathVariable String userId,@RequestHeader(SecurityConstants.INTERNAL_API_KEY_HEADER) String k){check(k);return s.status(userId);}@PostMapping("/verify") ResponseEntity<Void> verify(@RequestHeader(SecurityConstants.INTERNAL_API_KEY_HEADER) String k,@Valid @RequestBody InternalVerification r){check(k);s.verify(r.userId(),r.otpCode());return ResponseEntity.noContent().build();}private void check(String k){if(!key.equals(k))throw new UnauthorizedException("Invalid internal API key");}}
